-- 0018: persist the dive-deeper layer on daily readings.
--
-- The W2b proof lines render from reading.diveDeeper, but no column ever
-- stored it — every reading served from a row silently lost the layer,
-- so the day page's proof lines could never render for a returning
-- user. dive_deeper is generated by the same deterministic pipeline as
-- the rest of the reading, so storing it keeps the row the single
-- source of truth (no read-time regeneration, no divergence from the
-- persisted provenance). JSONB, nullable: rows written before this
-- migration carry no dive layer and render without one (never faked).
alter table public.daily_readings
  add column if not exists dive_deeper jsonb;
